// Split each markdown file into "## " sections, then each section into
// ~800-character chunks with ~100 characters of overlap (recursive splitter:
// paragraphs first, then lines, sentences, words).
const CHUNK_SIZE = 800;
const CHUNK_OVERLAP = 100;
const SEPARATORS = ['\n\n', '\n', '. ', ' '];

function recursiveSplit(text, separators = SEPARATORS) {
  if (text.length <= CHUNK_SIZE) return [text];
  const [sep, ...rest] = separators;
  if (sep === undefined) {
    const out = [];
    for (let i = 0; i < text.length; i += CHUNK_SIZE - CHUNK_OVERLAP) out.push(text.slice(i, i + CHUNK_SIZE));
    return out;
  }
  const pieces = text.split(sep).flatMap((p) => (p.length > CHUNK_SIZE ? recursiveSplit(p, rest) : [p]));
  const chunks = [];
  let current = '';
  for (const piece of pieces) {
    const candidate = current ? current + sep + piece : piece;
    if (candidate.length <= CHUNK_SIZE) {
      current = candidate;
      continue;
    }
    if (current) chunks.push(current);
    // Start the next chunk with the last words of the previous one.
    const tail = current.slice(-CHUNK_OVERLAP);
    const overlap = tail.includes(' ') ? tail.slice(tail.indexOf(' ') + 1) : '';
    current = overlap && (overlap + sep + piece).length <= CHUNK_SIZE ? overlap + sep + piece : piece;
  }
  if (current) chunks.push(current);
  return chunks.map((c) => c.trim()).filter(Boolean);
}

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const text = buffer.toString('utf8').replace(/\r\n/g, '\n');
  const sourceFile = items[i].binary.data.fileName;
  const titleMatch = text.match(/^# (.+)$/m);
  const docTitle = titleMatch ? titleMatch[1].trim() : sourceFile;

  for (const section of text.split(/^## /m).slice(1)) {
    const newline = section.indexOf('\n');
    const sectionTitle = (newline === -1 ? section : section.slice(0, newline)).trim();
    const body = newline === -1 ? '' : section.slice(newline + 1).trim();
    if (!body) continue;

    recursiveSplit(body).forEach((chunk, chunkIndex) => {
      results.push({
        json: {
          content: chunk,
          metadata: { source_file: sourceFile, section_title: sectionTitle, doc_title: docTitle, chunk_index: chunkIndex },
          // gemini-embedding-2 has no task_type: documents use this prefix (see CLAUDE.md).
          embed_text: `title: ${docTitle} - ${sectionTitle} | text: ${chunk}`,
        },
      });
    });
  }
}

if (results.length === 0) throw new Error('No chunks produced: is /data/knowledge_base mounted and non-empty?');
return results;

// Gemini batchEmbedContents accepts up to 100 texts per call.
// ~42 chunks = 1 call, which keeps us far below the free-tier rate limit.
const BATCH_SIZE = 100;
const chunks = $input.all().map((item) => item.json);
const batches = [];

for (let i = 0; i < chunks.length; i += BATCH_SIZE) {
  const batch = chunks.slice(i, i + BATCH_SIZE);
  batches.push({
    json: {
      rows: batch.map((c) => ({ content: c.content, metadata: c.metadata })),
      requests: batch.map((c) => ({
        model: 'models/gemini-embedding-2',
        content: { parts: [{ text: c.embed_text }] },
        outputDimensionality: 768,
      })),
    },
  });
}
return batches;

// Pair each embedding with its chunk (same order as the batch request).
const batches = $('Group into batches of 100').all();
const rows = [];

$input.all().forEach((item, i) => {
  const embeddings = item.json.embeddings || [];
  const batchRows = batches[i].json.rows;
  if (embeddings.length !== batchRows.length) {
    throw new Error(`Batch ${i}: expected ${batchRows.length} embeddings, got ${embeddings.length}`);
  }
  batchRows.forEach((row, j) => {
    const values = embeddings[j].values;
    if (values.length !== 768) throw new Error(`Embedding has ${values.length} dimensions, expected 768`);
    rows.push({ ...row, embedding: values });
  });
});

return [{ json: { rows, chunk_count: rows.length, file_count: new Set(rows.map((r) => r.metadata.source_file)).size } }];
